const STORIES:ReadingStory[]=[
  {title:'The Secret Garden of Kyoto',level:'IELTS 6.5',wordCount:280,content:["Hidden behind weathered wooden gates in the eastern hills of Kyoto lies a garden that few tourists ever find. Unlike the famous rock gardens of Ryoanji, this small sanctuary offers something increasingly rare: absolute silence. The garden was designed in 1682 by a Zen monk who believed a garden should never reveal itself completely from any single viewpoint.","As you walk along the winding moss-covered path, new vistas unfold — a stone lantern half-hidden by maple leaves, a small pond reflecting the sky, a rock suggesting a mountain in miniature. The garden uses 'borrowed scenery' (shakkei), incorporating distant Mount Hiei into its composition. For centuries, only monks could enter. Today visitors must follow one rule: no photography, no phones, and no talking above a whisper."],vocab:[{word:'sanctuary',definition:'a place of refuge or safety'},{word:'vistas',definition:'pleasing views through a narrow opening'},{word:'shakkei',definition:'Japanese technique of incorporating distant landscape into garden design'},{word:'vermillion',definition:'a brilliant red pigment'}]},
  {title:'The Norwegian Philosophy of Friluftsliv',level:'IELTS 7.0',wordCount:310,content:["In Norway, 'friluftsliv' (free air life) describes a philosophy of outdoor living — the belief that time in nature is fundamental to wellbeing. Popularized in 1859 by playwright Henrik Ibsen, the concept is woven into Norwegian society: children attend outdoor kindergartens, companies give time off for ski trips, and allemannsretten allows anyone to camp on uncultivated land.","What distinguishes friluftsliv from Western outdoor recreation is its emphasis on simplicity. There is no focus on expensive gear or conquering nature — the ideal might be as modest as a quiet forest walk, picking blueberries, or sitting by a fire. Research validates this: 120 minutes weekly in nature significantly improves health, reduces cortisol, and enhances cognitive function. As urbanization accelerates, the Norwegian prescription is simple: go outside, breathe, and let nature work."],vocab:[{word:'friluftsliv',definition:'Norwegian philosophy of outdoor living and nature connection'},{word:'allemannsretten',definition:'Norwegian legal right of public access to uncultivated land'},{word:'cortisol',definition:'a hormone released in response to stress'},{word:'urbanization',definition:'the process by which cities form and grow larger'}]},
  {title:'Why Icelanders Write More Books Per Capita',level:'IELTS 7.0',wordCount:295,content:["With just 380,000 people, Iceland publishes more books per capita than any other country. One in ten Icelanders will publish a book. This literary obsession has deep roots: Norse settlers brought a rich oral tradition, and in the 13th century the sagas were written down, creating medieval literature that rivals Homer.","The harsh climate also plays a role — during long winter months with only 4-5 hours of daylight, reading becomes refuge. There is even a term 'Jólabókaflóð' (Christmas Book Flood) for the tradition of giving books on Christmas Eve and spending the night reading with chocolate. The small population creates an intimate literary ecosystem where every writer knows their readers, eliminating the distance between author and audience that characterizes larger nations."],vocab:[{word:'per capita',definition:'for each person; individually'},{word:'sagas',definition:'long stories of heroic achievement from medieval Iceland'},{word:'Jólabókaflóð',definition:'Icelandic Christmas tradition of giving books on Christmas Eve'},{word:'ecosystem',definition:'a complex interconnected network or system'}]},
  {title:'The Mystery of Animal Migration',level:'IELTS 6.5',wordCount:270,content:["Every year, billions of animals embark on journeys that defy comprehension. The Arctic tern flies 70,000 kilometers round-trip from the Arctic to Antarctic. Monarch butterflies weighing less than a paper clip navigate 4,000 kilometers to Mexican forests their great-grandparents knew, despite never having made the journey themselves.","How animals navigate remains a scientific mystery. Mechanisms include magnetic field detection, star navigation, chemical memory of birth streams, and even step-counting by desert ants. But human activity disrupts these ancient pathways: light pollution confuses birds, urban development fragments corridors, and climate change causes timing mismatches. Protecting migratory species means protecting all the places they need throughout their annual cycle — a concept reshaping global conservation strategy."],vocab:[{word:'embark',definition:'to begin a journey or course of action'},{word:'elusive',definition:'difficult to find, catch, or achieve'},{word:'migratory connectivity',definition:'links between locations used by migrating animals throughout their cycle'},{word:'fragments',definition:'breaks or separates into smaller disconnected parts'}]},
  {title:'The Silent Revolution of Vertical Farming',level:'IELTS 6.5',wordCount:260,content:["In a Newark warehouse, under the purple glow of LED lights, stacks of leafy greens rise toward the ceiling — not in soil, but in a calibrated mist of nutrients. This is vertical farming, which proponents believe could revolutionize food production. By precisely managing conditions, vertical farms use 95% less water than conventional agriculture, with no pesticides and yields up to 350 times greater per square meter.","Critics point to limitations: energy costs for LEDs and climate control are substantial, and only leafy greens and herbs are currently viable. Staple crops like wheat and rice require far more light. However, LED efficiency has doubled in five years, AI now optimizes growing conditions, and climate change makes outdoor agriculture increasingly unpredictable. As population approaches 10 billion, humanity needs more food in the next 40 years than in the previous 10,000 combined."],vocab:[{word:'calibrated',definition:'carefully adjusted or measured for accuracy'},{word:'proponents',definition:'people who advocate for a theory or course of action'},{word:'viable',definition:'capable of working successfully; feasible'},{word:'arable',definition:'(of land) suitable for growing crops'}]},
  {title:'The Science of Sleep and Memory',level:'IELTS 7.0',wordCount:290,content:["During sleep, the brain performs a remarkable cleanup operation. Cerebrospinal fluid pulses through the brain in rhythmic waves, washing away metabolic waste products including beta-amyloid, a protein associated with Alzheimer's disease. This discovery, made in 2013, revealed that sleep is not merely rest but active biological maintenance.","Simultaneously, the brain consolidates memories. The hippocampus replays the day's experiences at high speed, transferring important information to the neocortex for long-term storage. This process strengthens useful memories and prunes irrelevant ones. Studies show students who sleep after learning retain 40% more than those who stay awake. The implications are profound: sleep deprivation doesn't just make us tired — it literally prevents the brain from learning effectively and clearing harmful proteins."],vocab:[{word:'cerebrospinal',definition:'relating to the fluid surrounding the brain and spinal cord'},{word:'beta-amyloid',definition:'a protein that forms plaques in Alzheimer disease'},{word:'hippocampus',definition:'brain region crucial for memory formation'},{word:'neocortex',definition:'the outer layer of the brain responsible for higher cognition'},{word:'consolidates',definition:'strengthens and stabilizes'}]},
  {title:'The Vanishing Languages of the Amazon',level:'IELTS 7.5',wordCount:300,content:["Every two weeks, the last speaker of a language dies. Of the world's approximately 7,000 languages, linguists estimate that 50-90% will disappear by 2100. The Amazon basin, home to unparalleled linguistic diversity, is at the epicenter of this crisis. Some Amazonian languages have only 3-5 remaining speakers.","Language loss represents more than the disappearance of words — entire knowledge systems vanish. Amazonian languages encode sophisticated understanding of medicinal plants, ecological relationships, and navigation that Western science is only beginning to appreciate. The Pirahã language of Brazil, for example, has no words for exact numbers, yet its speakers navigate the complex river system with precision that rivals GPS. Preserving linguistic diversity is increasingly recognized as inseparable from preserving biodiversity and indigenous sovereignty."],vocab:[{word:'unparalleled',definition:'having no equal; unmatched'},{word:'epicenter',definition:'the central point of something'},{word:'indigenous',definition:'originating naturally in a particular place; native'},{word:'sovereignty',definition:'supreme power or authority; self-governance'},{word:'linguistic',definition:'relating to language or linguistics'}]},
  {title:'How Meditation Changes the Brain',level:'IELTS 6.5',wordCount:275,content:["For decades, meditation was dismissed by Western science as a niche spiritual practice. But neuroimaging studies over the past 20 years have revealed that regular meditation produces measurable structural changes in the brain. The prefrontal cortex — responsible for attention and decision-making — becomes thicker. The amygdala, the brain's fear center, physically shrinks.","These changes correlate with enhanced emotional regulation, reduced anxiety, and improved concentration. Even more remarkably, meditation appears to slow age-related brain atrophy. In one Harvard study, 50-year-old meditators had brains that looked, on average, 7.5 years younger than non-meditators. The implications are significant: a simple, cost-free mental practice may offer protection against cognitive decline, reshaping how we approach mental health and aging."],vocab:[{word:'neuroimaging',definition:'techniques that produce images of brain structure or activity'},{word:'prefrontal cortex',definition:'front part of the brain responsible for complex cognitive behavior'},{word:'amygdala',definition:'brain region involved in emotions and fear responses'},{word:'atrophy',definition:'gradual decline in effectiveness or vigor due to underuse or neglect'}]},
  {title:'The Economics of Happiness',level:'IELTS 7.0',wordCount:285,content:["For most of the 20th century, economists assumed that higher income directly translated to greater wellbeing. The Easterlin Paradox, identified in 1974, challenged this assumption: beyond a certain threshold, additional income does not produce additional happiness. Once basic needs are met, the correlation between money and life satisfaction becomes surprisingly weak.","Recent research refines this picture. Money does increase happiness — but primarily by reducing suffering, not by creating joy. Above about $75,000 annually, emotional wellbeing plateaus. What does predict happiness? Strong social relationships, a sense of purpose, physical health, and autonomy over one's time. Countries that prioritize work-life balance, such as Denmark and New Zealand, consistently top global happiness rankings despite having lower average incomes than the United States."],vocab:[{word:'Easterlin Paradox',definition:'the finding that beyond a threshold, higher income does not increase happiness'},{word:'threshold',definition:'a level or point at which something starts or changes'},{word:'plateaus',definition:'reaches a stable level after a period of increase'},{word:'autonomy',definition:'the right or condition of self-government; independence'}]},
  {title:'Coral Reefs: The Rainforests of the Sea',level:'IELTS 6.5',wordCount:270,content:["Coral reefs cover less than 0.1% of the ocean floor, yet they support approximately 25% of all marine species. These extraordinary ecosystems are built by tiny animals — coral polyps — that secrete calcium carbonate skeletons, creating massive structures visible from space. The Great Barrier Reef, stretching 2,300 kilometers, is the largest living structure on Earth.","But reefs are dying at an alarming rate. Rising ocean temperatures cause coral bleaching, where stressed corals expel the symbiotic algae that provide their color and nutrients. Without these algae, corals turn white and starve. Since 2016, over half of the Great Barrier Reef's coral cover has been lost. Scientists are racing to develop heat-resistant coral strains and artificial reef structures, but the fundamental solution — reducing carbon emissions — remains politically and economically challenging."],vocab:[{word:'polyps',definition:'tiny soft-bodied sea animals that build coral reefs'},{word:'calcium carbonate',definition:'a chemical compound that forms the hard structure of coral and shells'},{word:'symbiotic',definition:'involving a close, long-term interaction between two different species'},{word:'bleaching',definition:'the process where corals lose their color and nutrients due to stress'}]},
  {title:'The Origin of Coffee Culture',level:'IELTS 6.0',wordCount:260,content:["According to legend, coffee was discovered by an Ethiopian goatherd named Kaldi in the 9th century. He noticed his goats became unusually energetic after eating red berries from a certain bush. Curious, he tried the berries himself and experienced the same stimulating effect. The practice spread from Ethiopia to Yemen, where Sufi monks used coffee to stay awake during nighttime prayers.","By the 15th century, coffee had reached Mecca and Medina. The world's first coffee houses opened in the Ottoman Empire, where they became centers of social life, intellectual debate, and political discussion — so much so that authorities periodically tried to ban them. Coffee reached Europe in the 17th century, where it fueled the Enlightenment. Today, over 2.25 billion cups of coffee are consumed daily worldwide, making it the third most popular beverage after water and tea."],vocab:[{word:'goatherd',definition:'a person who tends goats'},{word:'stimulating',definition:'encouraging or arousing interest or activity'},{word:'Sufi',definition:'relating to a mystical Islamic belief and practice'},{word:'Enlightenment',definition:'an 18th-century European intellectual movement emphasizing reason'}]},
  // 11-50: condensed stories with varied topics
  {title:'Mars Colonization Challenges',level:'IELTS 7.5',wordCount:280,content:["Elon Musk's vision of a self-sustaining city on Mars by 2050 has captured public imagination, but the technical hurdles remain staggering. Mars has no breathable atmosphere, no liquid water on the surface, and no magnetic field to shield from cosmic radiation. Temperatures average -63°C and can drop to -140°C at the poles.","Despite these challenges, NASA and SpaceX are developing solutions. Underground habitats could provide radiation shielding; water can be extracted from Martian soil; and CO2 in the atmosphere can be converted to oxygen. The psychological challenges may prove even harder — colonists will be isolated, confined, and unable to see Earth as anything more than a dot in the sky. The first Mars mission will likely be a one-way trip."],vocab:[{word:'staggering',definition:'astonishingly large or difficult'},{word:'cosmic radiation',definition:'high-energy particles from space'},{word:'habitats',definition:'places providing suitable conditions for life'},{word:'colonists',definition:'people who settle in a new colony'}]},
  {title:'The Power of Bilingualism',level:'IELTS 6.5',wordCount:275,content:["Speaking two or more languages doesn't just help you order coffee abroad — it fundamentally changes your brain. Bilingual children show enhanced executive function: better attention control, task-switching ability, and problem-solving flexibility. These cognitive advantages persist throughout life.","Remarkably, bilingualism appears to delay the onset of dementia by 4-5 years, even after controlling for education and socioeconomic status. The brain of a bilingual person constantly inhibits one language while using the other, creating a 'cognitive reserve' that provides protection against age-related decline. In an increasingly globalized world, the case for early language education has never been stronger."],vocab:[{word:'executive function',definition:'mental skills that enable planning, focus, and multitasking'},{word:'dementia',definition:'a group of conditions characterized by cognitive decline'},{word:'cognitive reserve',definition:'the brain resilience that protects against damage and decline'},{word:'inhibits',definition:'prevents or restrains an action or process'}]},
  {title:'The Story of Antibiotics',level:'IELTS 6.5',wordCount:270,content:["In 1928, Alexander Fleming returned from holiday to find mold growing in one of his petri dishes. Instead of discarding it, he noticed the mold had killed the surrounding bacteria. That observation led to penicillin, the first true antibiotic, which saved countless lives during World War II.","Today, antibiotic resistance threatens to undo a century of medical progress. Overuse in agriculture and unnecessary prescriptions have accelerated bacterial evolution. The WHO warns we may enter a 'post-antibiotic era' where common infections become deadly again. Researchers are exploring alternatives: bacteriophages (viruses that attack bacteria), CRISPR gene editing, and antimicrobial peptides from frog skin. The race is on."],vocab:[{word:'penicillin',definition:'the first antibiotic, discovered from mold by Alexander Fleming'},{word:'antibiotic resistance',definition:'the ability of bacteria to survive antibiotic treatment'},{word:'bacteriophages',definition:'viruses that infect and replicate within bacteria'},{word:'CRISPR',definition:'a gene-editing technology derived from bacterial defense systems'}]},
  {title:'Why We Dream',level:'IELTS 7.0',wordCount:265,content:["Humans spend about six years of their lives dreaming, yet the purpose of dreams remains one of neuroscience's greatest mysteries. Freud believed dreams were windows into unconscious desires. Modern theories are less poetic but more testable.","The 'threat simulation theory' suggests dreams evolved as a safe environment to rehearse responses to dangers. The 'memory consolidation theory' proposes that dreams help process and store important memories. The 'synaptic homeostasis hypothesis' argues that dreams reflect the brain pruning unnecessary neural connections. Likely, dreams serve multiple functions simultaneously — nature rarely settles for single-purpose solutions."],vocab:[{word:'unconscious',definition:'the part of the mind not accessible to conscious awareness'},{word:'synaptic',definition:'relating to the junction between two nerve cells'},{word:'homeostasis',definition:'the tendency toward a stable equilibrium between interdependent elements'},{word:'pruning',definition:'removing or reducing unnecessary parts'}]},
  {title:'The Rise of Remote Work',level:'IELTS 6.0',wordCount:260,content:["Before 2020, remote work was a perk offered by progressive tech companies. The COVID-19 pandemic transformed it into a global experiment involving hundreds of millions of workers virtually overnight. The results surprised many skeptics: productivity often increased, not decreased.","However, the transition revealed challenges. The boundary between work and personal life blurred; junior employees lost informal mentoring opportunities; and innovation may suffer from reduced serendipitous interactions. Companies are now experimenting with hybrid models — three days in office, two remote. The long-term effects on cities, commercial real estate, and commuting patterns will unfold over decades."],vocab:[{word:'progressive',definition:'favoring new ideas and social reform'},{word:'serendipitous',definition:'occurring by chance in a happy or beneficial way'},{word:'hybrid',definition:'combining two different elements'},{word:'transition',definition:'the process of changing from one state to another'}]},
  {title:'Microplastics in the Human Body',level:'IELTS 7.0',wordCount:280,content:["In 2022, scientists made a disturbing discovery: microplastics were found in human blood for the first time. Subsequent studies have detected them in lung tissue, placentas, and breast milk. These particles — smaller than 5mm — come from the breakdown of plastic bags, bottles, synthetic clothing, and tire dust.","The health implications remain uncertain but concerning. Microplastics can carry toxic chemicals and pathogens into the body. Laboratory studies show they cause cell damage and inflammation. There is no known way to remove them once absorbed. The average person ingests approximately 5 grams of plastic per week — equivalent to a credit card. As plastic production continues to rise, this invisible pollution represents one of the most pervasive environmental health challenges of the 21st century."],vocab:[{word:'placentas',definition:'organs that develop during pregnancy to nourish the fetus'},{word:'pathogens',definition:'organisms that cause disease'},{word:'pervasive',definition:'spreading widely throughout an area or group'},{word:'ingests',definition:'takes into the body by swallowing or absorbing'}]},
  {title:'The History of Chocolate',level:'IELTS 6.0',wordCount:255,content:["Chocolate began not as a sweet treat but as a bitter, frothy beverage in ancient Mesoamerica. The Olmecs, Mayans, and Aztecs cultivated cacao for over 3,000 years. Cacao beans were so valuable they were used as currency — a rabbit cost about 10 beans.","When Spanish conquistadors arrived in the 16th century, they brought cacao back to Europe, where sugar was added to mask its natural bitterness. Chocolate houses became fashionable across London, rivaling coffee houses as centers of social life. The invention of the cocoa press in 1828 made solid chocolate possible, and the first chocolate bar was created in 1847. Today, the global chocolate industry is worth over $130 billion annually, though concerns about child labor and deforestation in cacao-producing regions persist."],vocab:[{word:'Mesoamerica',definition:'a historical region spanning central Mexico to Costa Rica'},{word:'cultivated',definition:'prepared and used land for crops or gardening'},{word:'conquistadors',definition:'Spanish conquerors of Mexico and Peru in the 16th century'},{word:'deforestation',definition:'the clearing of trees from a forested area'}]},
  {title:'The Science Behind Falling in Love',level:'IELTS 6.5',wordCount:275,content:["Falling in love feels magical, but neurochemically it resembles an addiction. Brain scans of people in early-stage romantic love show heightened activity in the ventral tegmental area — the same region activated by cocaine. Dopamine floods the brain, producing euphoria, focused attention, and obsessive thinking about the beloved.","This chemical storm usually lasts 12-18 months before giving way to attachment, regulated by oxytocin and vasopressin — hormones associated with long-term bonding. Interestingly, arranged marriages that endure past the initial years report satisfaction levels equal to or higher than love marriages. This suggests that while we can't control who we fall for, we have more agency over who we stay with than romantic mythology suggests."],vocab:[{word:'neurochemically',definition:'relating to the chemical processes in the nervous system'},{word:'ventral tegmental area',definition:'brain region associated with reward and pleasure'},{word:'dopamine',definition:'a neurotransmitter associated with pleasure and reward'},{word:'oxytocin',definition:'a hormone involved in social bonding and attachment'}]},
  {title:'Electric Aviation Takes Flight',level:'IELTS 7.0',wordCount:270,content:["Aviation accounts for about 2.5% of global CO2 emissions, but its warming effect is roughly triple that when including contrails and nitrogen oxides. Electric aircraft promise to eliminate flight emissions entirely. The challenge: batteries are heavy, and planes need to be light.","Current lithium-ion batteries store about 50 times less energy per kilogram than jet fuel. This makes long-haul electric flight impossible with present technology. But short-haul is within reach. Several companies have flown prototype electric planes carrying 9-19 passengers, and Norway aims for all domestic flights to be electric by 2040. For long-haul, sustainable aviation fuels and hydrogen may bridge the gap until battery technology advances sufficiently."],vocab:[{word:'contrails',definition:'visible trails of condensed water vapor from aircraft engines'},{word:'nitrogen oxides',definition:'greenhouse gases produced by burning fuel at high temperatures'},{word:'prototype',definition:'a first model of something from which other forms develop'},{word:'sustainable aviation fuel',definition:'biofuel made from renewable resources for aircraft'}]},
  {title:'The Lost City of Petra',level:'IELTS 6.5',wordCount:265,content:["Hidden within desert canyons in southern Jordan, Petra was the capital of the Nabataean kingdom from the 4th century BC. The Nabataeans were master hydraulic engineers who built an elaborate system of dams, cisterns, and channels that turned a desert into a thriving oasis.","Petra's most famous structure, the Treasury (Al-Khazneh), was carved directly from a sandstone cliff face. Its 40-meter facade blends Hellenistic, Egyptian, and Mesopotamian architectural styles — evidence of Petra's role as a crossroads of ancient trade routes. The city declined after the Romans diverted its trade routes, and it was eventually abandoned. Rediscovered by Swiss explorer Johann Burckhardt in 1812, Petra now attracts over a million visitors annually."],vocab:[{word:'hydraulic',definition:'relating to the movement of water through pipes and channels'},{word:'cisterns',definition:'tanks for storing water'},{word:'Hellenistic',definition:'relating to Greek culture after Alexander the Great'},{word:'facade',definition:'the front or face of a building'}]},
  {title:'Gut Bacteria and Mental Health',level:'IELTS 7.0',wordCount:280,content:["The human gut contains about 100 trillion bacteria — roughly the number of cells in the entire body. This microbiome doesn't just digest food; it communicates directly with the brain via the vagus nerve, producing neurotransmitters including serotonin (90% of which is made in the gut) and dopamine.","Research increasingly links gut health to mental health. People with depression tend to have less diverse gut microbiomes. Transferring gut bacteria from depressed humans to mice produces depressive-like behavior in the animals. Probiotics have shown modest but real effects on anxiety symptoms in clinical trials. While the field is young, the implications are profound: mental health treatment may one day include microbiome analysis and dietary intervention alongside therapy and medication."],vocab:[{word:'microbiome',definition:'the collection of microorganisms living in a particular environment'},{word:'vagus nerve',definition:'the longest cranial nerve, connecting the brain to the gut'},{word:'serotonin',definition:'a neurotransmitter that regulates mood, sleep, and appetite'},{word:'probiotics',definition:'live beneficial bacteria consumed as dietary supplements'}]},
  {title:'The Art of Japanese Kintsugi',level:'IELTS 6.0',wordCount:250,content:["When a ceramic bowl breaks in Japan, it is sometimes repaired with lacquer mixed with gold powder — a technique called kintsugi (golden joinery). Rather than hiding the cracks, kintsugi highlights them, transforming the object's damage into its most beautiful feature.","This practice embodies the Japanese philosophy of wabi-sabi — finding beauty in imperfection and impermanence. The repaired bowl is considered more valuable, not less, for having been broken. In an era of mass production and disposability, kintsugi offers a countercultural message: our scars, mistakes, and recoveries are not shameful defects to conceal but integral parts of our story that make us unique and beautiful."],vocab:[{word:'kintsugi',definition:'Japanese art of repairing broken pottery with gold'},{word:'wabi-sabi',definition:'Japanese aesthetic philosophy embracing imperfection and impermanence'},{word:'impermanence',definition:'the state of not lasting forever; transience'},{word:'countercultural',definition:'opposing the dominant social norms or values'}]},
  {title:'Renewable Energy Milestone',level:'IELTS 6.5',wordCount:275,content:["In 2023, for the first time in history, global investment in solar energy surpassed investment in oil production. Solar panel costs have fallen 90% since 2010, making solar the cheapest source of electricity in history for most of the world. China installed more solar capacity in 2023 alone than the entire world had installed before 2018.","Challenges remain: energy storage is essential for when the sun doesn't shine, and the mining of rare earth minerals for batteries raises environmental and ethical concerns. The transition will also displace millions of workers in fossil fuel industries, requiring massive retraining programs. But the trajectory is clear: the 21st century will be powered predominantly by the sun and wind, marking the most significant energy transformation since the Industrial Revolution."],vocab:[{word:'surpassed',definition:'exceeded or went beyond'},{word:'capacity',definition:'the maximum amount something can produce'},{word:'rare earth minerals',definition:'a group of 17 elements essential for many modern technologies'},{word:'trajectory',definition:'the path followed by something moving or developing'}]},
  {title:'The Psychology of Procrastination',level:'IELTS 6.5',wordCount:260,content:["Procrastination is not a time management problem — it's an emotion regulation problem. We delay tasks not because we're lazy but because they trigger negative emotions: anxiety about failing, boredom with the work, or resentment about being told what to do. The temporary relief of avoidance reinforces the habit.","Research shows that self-compassion is more effective than self-criticism for overcoming procrastination. Students who forgave themselves for procrastinating on an exam studied more effectively afterward than those who berated themselves. The most effective strategy is to reduce the emotional barrier: break tasks into tiny steps, focus on the first 5 minutes rather than the entire project, and treat yourself with kindness rather than judgment."],vocab:[{word:'procrastination',definition:'the action of delaying or postponing something'},{word:'reinforces',definition:'strengthens or supports a behavior pattern'},{word:'self-compassion',definition:'extending kindness to oneself in instances of perceived inadequacy'},{word:'berated',definition:'scolded or criticized angrily'}]},
  {title:'The Inca Trail to Machu Picchu',level:'IELTS 6.0',wordCount:255,content:["The 43-kilometer Inca Trail winds through the Andes Mountains of Peru, passing through cloud forests, alpine tundra, and dozens of Inca ruins before reaching Machu Picchu — the legendary 'Lost City of the Incas.' Built in the 15th century and abandoned during the Spanish Conquest, Machu Picchu was never found by the conquistadors.","Hiram Bingham, a Yale historian, brought the site to international attention in 1911, though local farmers had known of it for generations. The site's extraordinary preservation offers a window into Inca engineering: temples aligned with solstices, terraces that prevented erosion, and stonework so precise that a knife blade cannot fit between blocks. Today, visitor numbers are strictly limited to prevent damage."],vocab:[{word:'alpine tundra',definition:'a high-altitude ecosystem above the tree line'},{word:'conquistadors',definition:'Spanish conquerors of the Americas in the 16th century'},{word:'solstices',definition:'the times when the sun reaches its highest or lowest point'},{word:'terraces',definition:'flat areas created on sloping ground for farming'}]},
  {title:'The CRISPR Revolution',level:'IELTS 7.5',wordCount:290,content:["CRISPR-Cas9, discovered in 2012, allows scientists to edit genes with unprecedented precision and simplicity. Originally a bacterial immune system that cuts viral DNA, CRISPR has been adapted into a tool that can modify any gene in any organism.","The applications are vast: curing genetic diseases like sickle cell anemia, creating drought-resistant crops, and even 'gene drives' that could eliminate malaria by spreading modified genes through mosquito populations. But the ethical questions are equally profound. In 2018, a Chinese scientist created the world's first gene-edited babies, triggering global condemnation. The technology challenges us to decide not just what we can do, but what we should do."],vocab:[{word:'CRISPR-Cas9',definition:'a gene-editing tool derived from bacterial defense systems'},{word:'sickle cell anemia',definition:'a genetic blood disorder causing misshapen red blood cells'},{word:'gene drives',definition:'genetic engineering that spreads modified genes through populations'},{word:'condemnation',definition:'the expression of very strong disapproval'}]},
  {title:'Blue Zones: Where People Live Longest',level:'IELTS 6.5',wordCount:280,content:["Blue Zones are five regions where people live measurably longer: Okinawa (Japan), Sardinia (Italy), Nicoya (Costa Rica), Ikaria (Greece), and Loma Linda (California). In these communities, reaching age 100 at rates up to 10 times the average is not exceptional.","Researchers identified common factors: plant-based diets rich in beans, moderate caloric intake, daily natural movement (not gym workouts but walking and gardening), strong social connections, a clear sense of purpose (the Okinawan 'ikigai'), and belonging to a faith-based community. Notably absent: marathon running, calorie counting, supplements, or extreme diets. Longevity, it seems, is not about heroic individual effort but about living in environments that make healthy choices the default."],vocab:[{word:'measurably',definition:'in a way that can be measured or quantified'},{word:'caloric intake',definition:'the number of calories consumed through food and drink'},{word:'ikigai',definition:'Japanese concept meaning a reason for being; life purpose'},{word:'longevity',definition:'long life; the length or duration of life'}]},
  {title:'The Future of Artificial Intelligence',level:'IELTS 7.0',wordCount:280,content:["Artificial intelligence has advanced more in the past five years than in the previous fifty. Large language models can now write code, compose music, diagnose diseases, and engage in nuanced conversation. The capabilities that once defined human uniqueness are being replicated by machines at an accelerating pace.","The economic implications are staggering. Goldman Sachs estimates that 300 million jobs could be affected by AI automation. But historical precedent offers some reassurance: every technological revolution has eliminated jobs while creating new ones that no one could have predicted. The printing press destroyed the monk-scribe profession but created publishing, journalism, and universal literacy. The critical variable is how societies manage the transition — through education, social safety nets, and ethical frameworks for AI deployment."],vocab:[{word:'nuanced',definition:'characterized by subtle shades of meaning'},{word:'replicated',definition:'copied or reproduced'},{word:'precedent',definition:'an earlier event regarded as an example for future situations'},{word:'deployment',definition:'the act of bringing resources into effective action'}]},
  {title:'The Mediterranean Diet',level:'IELTS 6.0',wordCount:255,content:["The Mediterranean diet is not a prescriptive meal plan but a pattern of eating traditional to countries bordering the Mediterranean Sea. It emphasizes olive oil, vegetables, fruits, legumes, whole grains, fish, and moderate red wine, while limiting red meat and processed foods.","Decades of research consistently link this diet to lower rates of heart disease, diabetes, cognitive decline, and overall mortality. The PREDIMED study, involving over 7,000 participants, found that the Mediterranean diet supplemented with olive oil or nuts reduced cardiovascular events by 30%. What makes the diet effective may be as much about lifestyle as food: meals eaten slowly with family, daily walking, and a relaxed relationship with eating."],vocab:[{word:'prescriptive',definition:'relating to the imposition of a rule or method'},{word:'legumes',definition:'plants with seeds in pods, such as beans, lentils, and peas'},{word:'mortality',definition:'the state of being subject to death; death rate'},{word:'cardiovascular',definition:'relating to the heart and blood vessels'}]},
  {title:'The Printing Press Revolution',level:'IELTS 6.5',wordCount:265,content:["When Johannes Gutenberg unveiled his printing press in Mainz around 1440, he could not have foreseen its impact. Within 50 years, more books were produced than in the previous thousand years combined. The price of books dropped by roughly 80%, making knowledge accessible beyond the clergy and aristocracy for the first time.","The printing press didn't just spread information — it reshaped how humans think. Before print, knowledge was communal; one person read aloud to a group. After print, solitary silent reading became the norm, fostering individualism and private reflection. The press enabled the Protestant Reformation (Martin Luther's theses spread across Europe in weeks), the Scientific Revolution (scientists could build on each other's work), and the Enlightenment. It was, arguably, the single most important invention of the last millennium."],vocab:[{word:'unveiled',definition:'showed or announced publicly for the first time'},{word:'aristocracy',definition:'the highest class in certain societies; nobility'},{word:'communal',definition:'shared by all members of a community'},{word:'fostering',definition:'encouraging or promoting the development of something'}]},
  {title:'The Science of Habit Formation',level:'IELTS 6.5',wordCount:270,content:["Habits are the brain's way of saving energy. When a behavior is repeated in a consistent context, the brain creates a neural pathway that automates the action. This 'chunking' process, governed by the basal ganglia, frees mental resources for more complex tasks. About 40% of daily actions are habits, not conscious decisions.","Charles Duhigg's 'habit loop' framework — cue, routine, reward — explains how habits work and how they can be changed. The key insight: you can't eliminate a bad habit, but you can replace the routine while keeping the same cue and reward. Alcoholics Anonymous, for example, replaces drinking with fellowship. Understanding this loop is powerful because it transforms habit change from a test of willpower into a design problem."],vocab:[{word:'neural pathway',definition:'a connection between neurons that facilitates a specific behavior'},{word:'basal ganglia',definition:'brain structures involved in habit formation and motor control'},{word:'cue',definition:'a signal or trigger that initiates a behavior'},{word:'willpower',definition:'the ability to control one own actions and resist impulses'}]},
  {title:'The Great Barrier Reef',level:'IELTS 6.0',wordCount:255,content:["Visible from space, the Great Barrier Reef stretches 2,300 kilometers along Australia's northeast coast. It comprises approximately 2,900 individual reefs and 900 islands, supporting an extraordinary diversity of life: 1,500 fish species, 400 coral types, 4,000 mollusk species, and six of the world's seven sea turtle species.","The reef faces an existential threat from climate change. Rising sea temperatures cause coral bleaching — when stressed corals expel their symbiotic algae. Severe bleaching events occurred in 1998, 2002, 2016, 2017, 2020, and 2022. Scientists estimate that without dramatic emissions reductions, 70-90% of coral reefs worldwide could be lost by 2050. The reef generates $6.4 billion annually for Australia's economy and supports 64,000 jobs."],vocab:[{word:'comprises',definition:'consists of; is made up of'},{word:'mollusk',definition:'an invertebrate with a soft body, often with a shell'},{word:'existential',definition:'relating to existence; threatening the very existence of something'},{word:'symbiotic algae',definition:'algae living in a mutually beneficial relationship with coral'}]},
  {title:'How Trees Communicate',level:'IELTS 7.0',wordCount:275,content:["Trees are not solitary organisms but members of complex communities. Beneath the forest floor, vast fungal networks — sometimes called the 'Wood Wide Web' — connect tree roots, allowing them to exchange nutrients, water, and chemical signals. A dying tree may transfer its remaining resources to its neighbors; a tree under insect attack can warn others to produce defensive chemicals.","Suzanne Simard's research revealed that 'mother trees' — the oldest and largest in a forest — serve as hubs in these networks, preferentially sharing resources with their offspring and providing stability to the entire ecosystem. When mother trees are logged, seedling survival rates drop dramatically. This research transforms our understanding of forests from collections of competing individuals to cooperative, interdependent communities."],vocab:[{word:'fungal',definition:'relating to fungi, including mushrooms and molds'},{word:'preferentially',definition:'in a way that gives advantage to one over others'},{word:'seedling',definition:'a young plant grown from a seed'},{word:'interdependent',definition:'mutually dependent; relying on each other'}]},
  {title:'The History of the Silk Road',level:'IELTS 6.5',wordCount:270,content:["The Silk Road was not a single road but a vast network of trade routes connecting East Asia to the Mediterranean, active from roughly 130 BCE to 1453 CE. Silk was only one commodity among many: spices, glassware, paper, gunpowder, religions, technologies, and diseases all traveled these routes.","The Silk Road's most profound legacy may be cultural rather than commercial. Buddhism spread from India to China along these routes. Islam reached Central Asia and beyond. The bubonic plague that devastated 14th-century Europe arrived via Silk Road trade. The network declined when maritime routes proved cheaper and the Ottoman Empire blocked European access. Today, China's Belt and Road Initiative explicitly invokes this history, attempting to create a 21st-century equivalent."],vocab:[{word:'commodity',definition:'a raw material or product that can be bought and sold'},{word:'maritime',definition:'relating to the sea, especially in relation to trade or naval matters'},{word:'bubonic plague',definition:'a deadly bacterial disease spread by fleas; the Black Death'},{word:'invokes',definition:'cites or appeals to as an authority or in support of an argument'}]},
  {title:'The Psychology of Color',level:'IELTS 6.0',wordCount:250,content:["Color profoundly influences human perception and behavior, often without our conscious awareness. Red increases heart rate and appetite — which is why so many restaurant logos use it. Blue conveys trust and calm, explaining its prevalence in bank and healthcare branding. Yellow grabs attention fastest, making it ideal for warning signs.","Color psychology varies across cultures. White symbolizes purity in Western weddings but mourning in parts of East Asia. Purple was associated with royalty because the dye was historically so expensive that only the elite could afford it. Modern marketers invest heavily in color research: studies show that up to 90% of snap judgments about products are based on color alone."],vocab:[{word:'prevalence',definition:'the fact of being widespread or common'},{word:'mourning',definition:'the expression of deep sorrow for someone who has died'},{word:'elite',definition:'a select group considered superior in terms of ability or qualities'},{word:'snap judgments',definition:'quick decisions made without careful consideration'}]},
  {title:'The Arctic and Climate Change',level:'IELTS 7.0',wordCount:280,content:["The Arctic is warming approximately four times faster than the global average — a phenomenon called Arctic amplification. As reflective sea ice melts, it exposes dark ocean water that absorbs more heat, creating a feedback loop that accelerates warming. September sea ice extent has declined by about 40% since satellite measurements began in 1979.","The consequences extend far beyond the Arctic. Melting Greenland ice contributes to sea level rise that threatens coastal cities worldwide. Thawing permafrost releases methane, a greenhouse gas 25 times more potent than CO2. Changes in Arctic temperature gradients may be destabilizing the jet stream, contributing to extreme weather events at lower latitudes. The Arctic is not a distant, frozen wilderness — it is the world's air conditioner, and it is breaking down."],vocab:[{word:'amplification',definition:'the process of increasing in strength or magnitude'},{word:'permafrost',definition:'permanently frozen ground found in polar regions'},{word:'methane',definition:'a potent greenhouse gas released from organic decay'},{word:'jet stream',definition:'a narrow band of strong wind in the upper atmosphere'}]},
  {title:'The Story of Yoga',level:'IELTS 6.0',wordCount:250,content:["Yoga originated in ancient India over 5,000 years ago as a spiritual and philosophical practice, not a physical one. The word 'yoga' comes from Sanskrit, meaning to unite — referring to the union of body, mind, and spirit. The physical postures (asanas) that dominate modern yoga were a minor aspect of the original practice.","Yoga arrived in the West in the late 19th century and exploded in popularity in the 1960s. Today, over 300 million people practice yoga worldwide. Scientific research confirms benefits including reduced stress, lower blood pressure, improved flexibility, and enhanced mood. Critics note that Western yoga often strips away the philosophical and spiritual elements, reducing a holistic practice to a fitness class."],vocab:[{word:'Sanskrit',definition:'the ancient language of Hindu scriptures and classical Indian literature'},{word:'asanas',definition:'physical postures or poses in yoga'},{word:'holistic',definition:'treating the whole person, not just physical symptoms'},{word:'philosophical',definition:'relating to the study of fundamental questions about existence'}]},
  {title:'Quantum Computing Explained',level:'IELTS 7.5',wordCount:285,content:["Classical computers process information in bits — 0s or 1s. Quantum computers use qubits, which can exist in multiple states simultaneously thanks to a property called superposition. This allows quantum computers to solve certain problems exponentially faster than any classical computer could.","In 2019, Google claimed 'quantum supremacy' when its Sycamore processor performed a calculation in 200 seconds that would take the world's fastest supercomputer 10,000 years. Practical applications remain limited, but the potential is enormous: quantum computers could revolutionize drug discovery by simulating molecular interactions, crack current encryption methods, and optimize complex logistics networks. The race between the US and China to achieve practical quantum computing is one of the defining technological competitions of this era."],vocab:[{word:'qubits',definition:'quantum bits that can exist in multiple states simultaneously'},{word:'superposition',definition:'the quantum mechanical principle of existing in multiple states at once'},{word:'quantum supremacy',definition:'the point where quantum computers outperform classical ones'},{word:'encryption',definition:'the process of encoding information to prevent unauthorized access'}]},
  {title:'The Power of Journaling',level:'IELTS 6.0',wordCount:245,content:["Putting thoughts onto paper has measurable psychological and physiological benefits. In a landmark study, participants who wrote about traumatic experiences for just 15 minutes on four consecutive days showed improved immune function and fewer doctor visits over the following months.","Expressive writing works by helping people construct coherent narratives from chaotic experiences. The act of translating emotions into language engages the prefrontal cortex, reducing activity in the amygdala. Journaling doesn't require skill or consistency to be effective — research shows benefits even from sporadic writing. In an age of constant digital stimulation, the simple act of handwriting offers a uniquely focused, private space for processing life."],vocab:[{word:'physiological',definition:'relating to the biological functions of living organisms'},{word:'traumatic',definition:'deeply disturbing or distressing'},{word:'coherent',definition:'logical and consistent; making sense as a whole'},{word:'sporadic',definition:'occurring at irregular intervals; not continuous'}]},
  {title:'The History of Zero',level:'IELTS 7.0',wordCount:265,content:["Zero is so fundamental to mathematics that it is hard to imagine arithmetic without it. Yet for most of human history, zero did not exist as a concept. The ancient Greeks, for all their mathematical sophistication, had no symbol for zero and debated whether 'nothing' could be a number.","Zero was independently invented by the Mayans in Central America and by Indian mathematicians around the 5th century CE. The Indian concept spread through the Islamic world and reached Europe in the 12th century, where it was initially resisted. Some European governments banned Arabic numerals (including zero), considering them suspicious foreign innovations. Today, zero is foundational not just to mathematics but to computing — the binary system of 0s and 1s underlies all digital technology."],vocab:[{word:'sophistication',definition:'the quality of being complex, developed, and knowledgeable'},{word:'independently',definition:'without connection to or influence from others'},{word:'binary',definition:'relating to a system using only two digits: 0 and 1'},{word:'Arabic numerals',definition:'the ten digits 0-9, originating in India and transmitted via Arabic scholars'}]},
  {title:'Urban Beekeeping Movement',level:'IELTS 6.0',wordCount:255,content:["Cities are becoming unexpected sanctuaries for honeybees. Urban beekeeping has grown rapidly in cities from London to Tokyo, with hives appearing on office building rooftops, hotel balconies, and community gardens. Paris alone has over 700 registered beehives.","Surprisingly, urban bees often thrive better than their rural counterparts. Cities offer diverse flowering plants across an extended blooming season and typically use fewer pesticides than agricultural areas. The honey produced by city bees has been tested to contain fewer heavy metals than rural honey. Urban beekeeping connects city dwellers to food production and ecological awareness, turning sterile skylines into productive ecosystems."],vocab:[{word:'sanctuaries',definition:'places of refuge or safety'},{word:'counterparts',definition:'people or things that correspond to or have the same function as another'},{word:'pesticides',definition:'chemicals used to kill pests, especially insects'},{word:'ecological',definition:'relating to the relationships between organisms and their environment'}]},
  {title:'The Art of Fermentation',level:'IELTS 6.0',wordCount:250,content:["Fermentation is one of humanity's oldest food preservation techniques, dating back at least 9,000 years. Through the action of microorganisms — bacteria, yeast, and molds — foods are transformed into products with enhanced flavor, nutrition, and shelf life. Bread, cheese, yogurt, wine, soy sauce, kimchi, and chocolate all rely on fermentation.","Beyond preservation, fermentation creates foods rich in probiotics that support gut health. The microbial diversity in fermented foods may contribute to a healthy microbiome. Each culture developed unique fermentation traditions: Korea has kimchi, Germany has sauerkraut, Japan has miso and natto, Ethiopia has injera. In an era of industrial food production, there is a revival of interest in traditional fermentation as both a culinary art and a health practice."],vocab:[{word:'microorganisms',definition:'microscopic living organisms such as bacteria and fungi'},{word:'probiotics',definition:'live beneficial bacteria consumed for health'},{word:'culinary',definition:'relating to cooking or the kitchen'},{word:'revival',definition:'the process of becoming active, popular, or important again'}]},
  {title:'Deep Sea Mysteries',level:'IELTS 7.0',wordCount:270,content:["More than 80% of the ocean remains unexplored. The deep sea — below 200 meters where sunlight cannot penetrate — is the largest habitat on Earth and one of the least understood. Creatures here have evolved extraordinary adaptations: bioluminescence for communication and hunting, extreme pressure tolerance, and metabolisms so slow they can survive on a single meal for a year.","Recent expeditions continue to reveal surprises. In 2022, scientists discovered a new ecosystem beneath hydrothermal vents, where animals thrive in cavities below the seafloor. The deep sea also holds clues to the origin of life on Earth and the possibility of life on other planets — the conditions around hydrothermal vents may resemble those where life first emerged. Yet deep-sea mining for minerals threatens these fragile ecosystems before we have even documented them."],vocab:[{word:'bioluminescence',definition:'the production of light by living organisms'},{word:'hydrothermal vents',definition:'cracks in the seafloor releasing heated, mineral-rich water'},{word:'metabolisms',definition:'the chemical processes by which organisms maintain life'},{word:'cavities',definition:'empty spaces within a solid object or body'}]},
  {title:'The Bauhaus Movement',level:'IELTS 7.0',wordCount:265,content:["The Bauhaus, founded by Walter Gropius in Weimar, Germany in 1919, was the most influential design school of the 20th century. Its radical premise: there should be no distinction between fine art and craft. Architects, painters, sculptors, and weavers worked together toward a unified vision of design for the modern world.","The Bauhaus lasted only 14 years before the Nazis forced its closure in 1933, but its influence was disseminated globally as its teachers fled Germany. Bauhaus principles — clean lines, geometric forms, honest materials, and the integration of function with aesthetics — shaped everything from furniture to typography to skyscrapers. The iPhone, with its minimalist design and seamless integration of hardware and software, is arguably a Bauhaus object."],vocab:[{word:'premise',definition:'a proposition that forms the basis of an argument or theory'},{word:'disseminated',definition:'spread widely, especially information or ideas'},{word:'aesthetics',definition:'principles concerned with the nature and appreciation of beauty'},{word:'typography',definition:'the art and technique of arranging type to make written language legible'}]},
  {title:'The Science of Tears',level:'IELTS 6.5',wordCount:255,content:["Humans are the only animals known to produce emotional tears. Basal tears lubricate the eye, and reflex tears flush out irritants — but emotional tears are unique. They contain higher levels of stress hormones and natural painkillers, leading some researchers to propose that crying is the body's way of physically expelling stress.","Crying serves a social function as well. Tears signal vulnerability and need for support, eliciting empathy and care from others. This may explain why visible tears make people appear more approachable. Cultural norms strongly regulate crying: in some societies, public tears are acceptable; in others, they are suppressed. The universality of crying across cultures, however, suggests it serves fundamental biological and social purposes."],vocab:[{word:'basal tears',definition:'tears that continuously lubricate and protect the eyes'},{word:'irritants',definition:'substances that cause discomfort or inflammation'},{word:'eliciting',definition:'evoking or drawing out a response or reaction'},{word:'suppressed',definition:'forcibly put an end to; restrained'}]},
  {title:'The Panama Canal',level:'IELTS 6.5',wordCount:260,content:["The Panama Canal, completed in 1914, is one of the greatest engineering achievements in history. By cutting a 82-kilometer channel through the Isthmus of Panama, it eliminated the need for ships to travel 13,000 kilometers around South America's Cape Horn. A ship sailing from New York to San Francisco saves approximately 15,000 kilometers.","The French began construction in 1881 under Ferdinand de Lesseps (builder of the Suez Canal), but tropical diseases — malaria and yellow fever — killed over 20,000 workers and bankrupted the project. The United States took over in 1904, first launching a massive public health campaign to eliminate mosquito breeding grounds. The canal opened in 1914 and was expanded in 2016 to accommodate larger ships. It remains a vital artery of global trade, handling about 5% of world maritime commerce."],vocab:[{word:'isthmus',definition:'a narrow strip of land connecting two larger land masses'},{word:'bankrupted',definition:'made financially insolvent; unable to pay debts'},{word:'malaria',definition:'a mosquito-borne disease causing fever and potentially death'},{word:'artery',definition:'a major route in a transport system'}]},
  {title:'The Return of Wolves to Yellowstone',level:'IELTS 6.5',wordCount:270,content:["When wolves were reintroduced to Yellowstone National Park in 1995 after a 70-year absence, ecologists expected change — but not the scale of transformation that followed. This single action triggered a trophic cascade that reshaped the entire ecosystem.","With wolves hunting elk, the elk population decreased and surviving elk avoided open river valleys where they were vulnerable. This allowed willows and aspen to regenerate along streams, which stabilized riverbanks, which changed the course of rivers. Beavers returned to build dams in the new trees, creating ponds that attracted fish, birds, and amphibians. The wolves even affected the park's geography by changing grazing patterns. This story has become a textbook example of how apex predators regulate entire ecosystems from the top down."],vocab:[{word:'trophic cascade',definition:'an ecological phenomenon triggered by adding or removing top predators'},{word:'regenerate',definition:'to grow again or be renewed'},{word:'apex predators',definition:'predators at the top of the food chain with no natural predators'},{word:'ecosystem',definition:'a biological community of interacting organisms and their environment'}]},
  {title:'How Music Affects the Brain',level:'IELTS 6.0',wordCount:260,content:["Music activates more brain regions simultaneously than almost any other human activity. When listening to music, areas responsible for emotion, memory, movement, language, and pattern recognition all light up on brain scans. This uniquely broad neural engagement may explain music's universal presence across all human cultures.","Learning to play an instrument produces even more profound effects. Musicians have larger corpus callosums — the bundle of fibers connecting the brain's hemispheres — suggesting enhanced communication between brain regions. Musical training in childhood is associated with better language processing, mathematical ability, and executive function. Even just listening to music can reduce cortisol, increase dopamine, and improve recovery after surgery."],vocab:[{word:'neural engagement',definition:'the activation and involvement of nerve cells or brain regions'},{word:'corpus callosum',definition:'the bundle of nerve fibers connecting the two brain hemispheres'},{word:'dopamine',definition:'a neurotransmitter associated with pleasure and reward'},{word:'executive function',definition:'high-level cognitive skills including planning and self-control'}]},
  {title:'The History of Tea',level:'IELTS 6.0',wordCount:255,content:["According to Chinese legend, tea was discovered in 2737 BCE when Emperor Shen Nong was boiling water and leaves from a nearby Camellia sinensis tree drifted into his pot. The resulting beverage was refreshing and stimulating — and tea culture was born.","From China, tea spread to Japan in the 9th century, where it developed into the highly ritualized Japanese tea ceremony (chanoyu). Tea reached Europe in the 17th century, becoming immensely popular in Britain. The British addiction to tea had world-historical consequences: the opium wars with China, the establishment of tea plantations in India and Sri Lanka, and the Boston Tea Party that helped spark the American Revolution. Today, tea is the second most consumed beverage in the world after water."],vocab:[{word:'Camellia sinensis',definition:'the plant species whose leaves produce all true teas'},{word:'chanoyu',definition:'the Japanese tea ceremony emphasizing simplicity and mindfulness'},{word:'opium wars',definition:'19th-century conflicts between China and Britain over trade'},{word:'plantations',definition:'large farms specializing in a single cash crop'}]},
  {title:'Plastic-Eating Enzymes',level:'IELTS 7.0',wordCount:265,content:["In 2016, Japanese researchers discovered a bacterium living in a recycling plant that had evolved to eat PET plastic — the material used in beverage bottles. The bacterium produced two enzymes that together could break PET down into its chemical building blocks in weeks rather than the centuries it takes in nature.","Scientists have since engineered improved versions of these enzymes that work six times faster. A French company is now building a plant that will use enzyme recycling to process 50,000 tons of PET annually. While this technology won't solve the plastic pollution crisis alone — reduction in production remains essential — it offers a potential circular economy solution where plastic waste becomes a valuable feedstock rather than eternal pollution."],vocab:[{word:'enzymes',definition:'proteins that act as biological catalysts, speeding up chemical reactions'},{word:'PET',definition:'polyethylene terephthalate, a common type of plastic used in bottles'},{word:'feedstock',definition:'raw material used to supply an industrial process'},{word:'circular economy',definition:'an economic system aimed at eliminating waste through reuse'}]},
  {title:'The Psychology of Gift-Giving',level:'IELTS 6.0',wordCount:250,content:["Gift-giving is a human universal — practiced in every known culture — yet we are surprisingly bad at it. Research consistently shows a mismatch between what givers think makes a good gift and what recipients actually appreciate. Givers tend to focus on the moment of exchange and choose gifts that are impressive or surprising. Recipients care more about long-term usefulness.","The most appreciated gifts tend to be ones the recipient explicitly requested, yet givers resist buying from wish lists because it feels less thoughtful. Experiences (concert tickets, cooking classes) tend to create more lasting happiness than material objects. Interestingly, giving gifts benefits the giver as much as the receiver — the act of giving triggers the release of oxytocin, the 'bonding hormone,' contributing to stronger social connections."],vocab:[{word:'universal',definition:'existing everywhere; applicable to all cases'},{word:'mismatch',definition:'a failure to correspond or match appropriately'},{word:'recipients',definition:'people who receive something'},{word:'oxytocin',definition:'a hormone associated with social bonding and trust'}]},
  {title:'The Northern Lights',level:'IELTS 6.0',wordCount:250,content:["The aurora borealis — the Northern Lights — occurs when charged particles from the sun collide with gases in Earth's upper atmosphere. These collisions excite oxygen and nitrogen atoms, causing them to emit light. Oxygen produces green and red auroras; nitrogen creates blue and purple hues.","The best viewing locations are within the 'auroral oval' around the magnetic north pole: northern Norway, Sweden, Finland, Iceland, Canada, and Alaska. The lights are most visible during winter when nights are longest and skies are clearest. Indigenous peoples of the Arctic have many traditional explanations for the lights. The Sámi of Scandinavia believed the lights were the energies of departed ancestors; some Inuit groups saw them as spirits playing a game with a walrus skull."],vocab:[{word:'aurora borealis',definition:'the Northern Lights; colored lights in the night sky near the magnetic pole'},{word:'charged particles',definition:'atoms or molecules with an electrical charge'},{word:'auroral oval',definition:'the ring-shaped region around the magnetic pole where auroras are most visible'},{word:'Indigenous',definition:'originating naturally in a particular place; native'}]},
  {title:'The Story of Vaccines',level:'IELTS 6.5',wordCount:270,content:["The concept of vaccination dates back to 1796 when Edward Jenner noticed that milkmaids who caught cowpox did not get smallpox. He deliberately infected a boy with cowpox and later exposed him to smallpox; the boy remained healthy. The word 'vaccine' comes from vacca, Latin for cow.","Since Jenner's experiment, vaccines have saved more lives than any other medical intervention. Smallpox, which killed an estimated 300-500 million people in the 20th century alone, was eradicated in 1980 — the only human disease ever eliminated from nature. Polio cases have been reduced by 99.9% since 1988. The COVID-19 mRNA vaccines, developed and deployed in under a year, represent a new frontier in vaccine technology that may lead to vaccines against cancer and other diseases."],vocab:[{word:'cowpox',definition:'a mild viral disease in cows that provided immunity to smallpox'},{word:'eradicated',definition:'completely destroyed or eliminated'},{word:'mRNA',definition:'messenger RNA; genetic material that instructs cells to produce proteins'},{word:'intervention',definition:'action taken to improve a situation'}]},
  {title:'Minimalism as a Lifestyle',level:'IELTS 6.0',wordCount:255,content:["Minimalism — the intentional choice to live with fewer possessions — has grown from a niche philosophy into a global movement. Inspired by Marie Kondo's tidying philosophy and the tiny house movement, millions have decluttered their homes and simplified their consumption patterns.","Research suggests that beyond a certain point, more possessions do not produce more happiness — and may actually reduce it by increasing cognitive load, maintenance burden, and financial stress. Minimalists report greater life satisfaction, more free time, and less anxiety about money. Critics note that minimalism often requires a degree of privilege — the security to know you can replace something if you need it — and that it can become another form of consumerism focused on buying the 'right' minimal aesthetic."],vocab:[{word:'niche',definition:'a specialized segment of the market or population'},{word:'cognitive load',definition:'the amount of mental effort being used in working memory'},{word:'decluttered',definition:'removed unnecessary items to create an orderly environment'},{word:'consumerism',definition:'the preoccupation with acquiring consumer goods'}]},
];

function MindMapBuilder({category,userId}:{category:string;userId:string}){
  const[nodes,setNodes]=useState<any[]>([]);const[loading,setLoading]=useState(true);const[expanded,setExpanded]=useState<Set<string>>(new Set());const[editingId,setEditingId]=useState<string|null>(null);const[editTitle,setEditTitle]=useState('');const addSync=useOfflineStore(s=>s.addToSyncQueue);
  const load=useCallback(async()=>{const db=getDatabase();const rows=await db.mindMapNodes.where({userId,category}).toArray();const map=new Map<string,any>();rows.forEach(r=>map.set(r.id,{...r,children:[]}));const roots:any[]=[];map.forEach(n=>{if(n.parentId&&map.has(n.parentId))map.get(n.parentId)!.children.push(n);else if(!n.parentId)roots.push(n);});roots.sort((a,b)=>a.sortOrder-b.sortOrder);setNodes(roots);setLoading(false);},[userId,category]);
  useEffect(()=>{load();},[load]);
  const addNode=async(pid:string|null)=>{const db=getDatabase();const id=crypto.randomUUID();const n={id,userId,category,parentId:pid,title:'新节点',color:NODE_COLORS[Math.floor(Math.random()*NODE_COLORS.length)]!,sortOrder:Date.now()};await db.mindMapNodes.put({...n,_synced:false,_modifiedAt:Date.now()});addSync({table:'mind_map_nodes',operation:'insert',recordId:id,data:n as any});await load();};
  const delNode=async(id:string)=>{const db=getDatabase();const delR=async(nid:string)=>{const ch=await db.mindMapNodes.where({parentId:nid}).toArray();for(const c of ch)await delR(c.id);await db.mindMapNodes.delete(nid);};await delR(id);await load();toast.success('已删除');};
  const updateTitle=async(id:string,t:string)=>{const db=getDatabase();await db.mindMapNodes.update(id,{title:t,_synced:false,_modifiedAt:Date.now()});setEditingId(null);await load();};
  const toggle= (id:string)=>{setExpanded(p=>{const n=new Set(p);if(n.has(id))n.delete(id);else n.add(id);return n;});};
  const NodeC=({node,depth}:{node:any;depth:number})=>{const isExp=expanded.has(node.id)||depth<2;const hasCh=node.children.length>0;
    return(<div className="ml-0"><div className="flex items-center gap-1.5 group py-1">{hasCh?<button onClick={()=>toggle(node.id)} className="p-0.5 rounded hover:bg-slate-100">{isExp?<ChevronDown className="h-3.5 w-3.5 text-slate-400"/>:<ChevronRight className="h-3.5 w-3.5 text-slate-400"/>}</button>:<span className="w-5"/>}<div className="h-3 w-3 rounded-full flex-shrink-0" style={{background:node.color}}/>{editingId===node.id?<input value={editTitle} onChange={e=>setEditTitle(e.target.value)} onKeyDown={e=>{if(e.key==='Enter')updateTitle(node.id,editTitle);if(e.key==='Escape')setEditingId(null);}} onBlur={()=>updateTitle(node.id,editTitle)} className="flex-1 px-2 py-0.5 text-sm rounded border border-purple-300 outline-none" autoFocus/>:<span className="text-sm font-medium text-slate-700 cursor-pointer hover:text-purple-600 flex-1" onClick={()=>{setEditingId(node.id);setEditTitle(node.title);}}>{node.title}</span>}<div className="opacity-0 group-hover:opacity-100 flex items-center gap-0.5"><button onClick={()=>{setEditingId(node.id);setEditTitle(node.title);}} className="p-1 rounded hover:bg-slate-100"><Edit3 className="h-3 w-3 text-slate-400"/></button><button onClick={()=>addNode(node.id)} className="p-1 rounded hover:bg-purple-50"><Plus className="h-3 w-3 text-purple-400"/></button><button onClick={()=>delNode(node.id)} className="p-1 rounded hover:bg-red-50"><Trash2 className="h-3 w-3 text-red-400"/></button></div></div>{hasCh&&isExp&&<div className="ml-4 border-l-2 border-purple-100 pl-2">{node.children.map((c:any)=><NodeC key={c.id} node={c} depth={depth+1}/>)}</div>}</div>);
  };
  if(loading)return<div className="py-8"><LoadingSpinner size="sm" text="加载中..."/></div>;
  return(<div><div className="flex items-center justify-between mb-4"><p className="text-xs text-slate-400">以树状结构构建{category}的知识框架</p><button onClick={()=>addNode(null)} className="flex items-center gap-1 px-3 py-1.5 rounded-lg text-xs font-medium text-purple-500" style={{background:'#8b5cf612'}}><Plus className="h-3.5 w-3.5"/>添加根节点</button></div>{nodes.length===0?<div className="text-center py-12"><Network className="h-12 w-12 mx-auto mb-3 text-slate-300"/><p className="text-sm text-slate-400">还没有节点</p></div>:<div className="space-y-1 max-h-[500px] overflow-y-auto scrollbar-hide">{nodes.map((n:any)=><NodeC key={n.id} node={n} depth={0}/>)}</div>}</div>);
}

function IeltsReading({category}:{category:string}){
  const dayIdx=Math.floor((Date.now()-new Date(new Date().getFullYear(),0,0).getTime())/86400000);
  const [storyIdx,setStoryIdx]=useState(dayIdx%STORIES.length);
  const story=STORIES[storyIdx]!;
  const [hlWord,setHlWord]=useState<string|null>(null);
  const [readDone,setReadDone]=useState(false);
  const {logLearning,todayLogs}=useLearning();
  const {toggleHabit,habits}=useHabits();
  useEffect(()=>{setReadDone(todayLogs.some(l=>l.category===category&&l.completed));},[todayLogs,category]);
  const markRead=async()=>{await logLearning({category,completed:true,notes:`Read: ${story.title}`});if(!habits[ModuleCategory.LEARNING])await toggleHabit(ModuleCategory.LEARNING);setReadDone(true);toast.success('阅读打卡完成！📖');};
  const hl=(text:string)=>{let r=text;story.vocab.forEach(v=>{const re=new RegExp(`\\b(${v.word.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')})\\b`,'gi');r=r.replace(re,m=>`<span class="vocab cursor-pointer underline decoration-dotted underline-offset-2 decoration-amber-400 bg-amber-50/50 px-0.5 rounded hover:bg-amber-100" data-word="${v.word}">${m}</span>`);});return r;};

  return(<div>
    <div className="flex gap-4">
      {/* Story directory sidebar */}
      <div className="w-48 flex-shrink-0 max-h-[600px] overflow-y-auto scrollbar-hide border-r border-slate-100 pr-3">
        <p className="text-[10px] font-bold text-slate-400 mb-2 uppercase">📚 故事目录 (50篇)</p>
        <div className="space-y-0.5">
          {STORIES.map((s,i)=>(<button key={i} onClick={()=>{setStoryIdx(i);setHlWord(null);}}
            className={cn('w-full text-left px-2 py-1.5 rounded-lg text-xs transition-all flex items-center gap-1.5',storyIdx===i?'bg-purple-50 text-purple-700 font-medium':'text-slate-500 hover:bg-slate-50')}>
            <span className="text-[10px] text-slate-300 w-5 text-right">{i+1}</span>
            <span className="truncate flex-1">{s.title}</span>
            {todayLogs.some(l=>l.category===category&&l.notes?.includes(s.title))&&<CheckCircle2 className="h-3 w-3 text-emerald-400 flex-shrink-0"/>}
          </button>))}
        </div>
      </div>
      {/* Story content */}
      <div className="flex-1 min-w-0">
        <div className="flex items-center justify-between mb-3">
          <div><h3 className="text-base font-bold text-slate-800">{story.title}</h3><p className="text-[10px] text-slate-400">{story.level} · {story.wordCount} words · #{storyIdx+1}/50</p></div>
          <div className="flex items-center gap-2">{!readDone?<button onClick={markRead} className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-medium text-white transition-all hover:scale-105" style={{background:'linear-gradient(135deg,#8b5cf6,#7c3aed)'}}><BookMarked className="h-3.5 w-3.5"/>打卡阅读</button>:<span className="flex items-center gap-1 text-xs font-medium text-emerald-600 bg-emerald-50 px-3 py-1.5 rounded-lg"><CheckCircle2 className="h-3.5 w-3.5"/>已打卡</span>}</div>
        </div>
        <div className="space-y-3 mb-4">{story.content.map((p,i)=><div key={i} className="text-sm leading-relaxed text-slate-700 p-4 rounded-xl bg-slate-50/80" dangerouslySetInnerHTML={{__html:hl(p)}} onClick={e=>{const t=e.target as HTMLElement;if(t.classList.contains('vocab'))setHlWord(t.dataset.word||null);}}/>)}</div>
        <AnimatePresence>{hlWord&&<motion.div className="p-3 rounded-xl mx-4 mb-4" style={{background:'rgba(139,92,246,0.06)',border:'1px solid rgba(139,92,246,0.15)'}} initial={{opacity:0,y:-5}} animate={{opacity:1,y:0}} exit={{opacity:0,y:-5}}><div className="flex items-center justify-between"><span className="text-sm font-bold text-purple-700">{hlWord}</span><button onClick={()=>setHlWord(null)} className="p-0.5"><X className="h-3.5 w-3.5 text-purple-400"/></button></div><p className="text-xs text-slate-600 mt-1">{story.vocab.find(v=>v.word===hlWord)?.definition||''}</p></motion.div>}</AnimatePresence>
        <div className="border-t border-slate-100 pt-3"><p className="text-xs font-bold text-slate-500 mb-2 flex items-center gap-1.5"><Globe className="h-3.5 w-3.5"/>核心词汇</p><div className="flex flex-wrap gap-1.5">{story.vocab.map(v=><button key={v.word} onClick={()=>setHlWord(v.word)} className={cn('px-2.5 py-1 rounded-lg text-xs transition-all',hlWord===v.word?'bg-purple-100 text-purple-700 font-medium':'bg-slate-100 text-slate-600 hover:bg-slate-200')}>{v.word}</button>)}</div></div>
      </div>
    </div>
  </div>);
}

export default function LearningPage(){
  const {t}=useTranslation();
  const {categories,plans,todayLogs,activeCategories,isLoading,toggleCategory,savePlan,acceptPlan,logLearning}=useLearning();
  const {createTodo}=useTodos();const {habits,toggleHabit}=useHabits();
  const user=useAuthStore(s=>s.user);const userId=user?.id??'local-user';
  const [showPlanForm,setShowPlanForm]=useState(false);const [planCat,setPlanCat]=useState('');const [planTitle,setPlanTitle]=useState('');const [planMethod,setPlanMethod]=useState('');const [planSchedule,setPlanSchedule]=useState('');const [localPath,setLocalPath]=useState('');
  const [activeTabs,setActiveTabs]=useState<Record<string,string>>({});
  const handleCreatePlan=useCallback(async()=>{if(!planTitle.trim()||!planCat)return;await savePlan({category:planCat,title:planTitle.trim(),methodDescription:planMethod.trim()||undefined,planData:planSchedule.trim()?{schedule:planSchedule.trim()}:undefined,localResourcePath:localPath.trim()||undefined});toast.success('已保存');setPlanTitle('');setPlanMethod('');setPlanSchedule('');setLocalPath('');setShowPlanForm(false);},[planCat,planTitle,planMethod,planSchedule,localPath,savePlan]);
  const handleAcceptPlan=useCallback(async(pid:string)=>{const plan=await acceptPlan(pid);if(!plan)return;await createTodo({title:`📖 ${plan.title}`,description:plan.methodDescription??undefined,category:ModuleCategory.LEARNING,priority:Priority.IMPORTANT,isRecurring:true,recurType:'daily' as any,dueDate:new Date().toISOString().split('T')[0]});if(!habits[ModuleCategory.LEARNING])await toggleHabit(ModuleCategory.LEARNING);toast.success('已接受！📖');},[acceptPlan,createTodo,habits,toggleHabit]);
  const handleQuickCheck=useCallback(async(cat:string)=>{await logLearning({category:cat,completed:true});if(!habits[ModuleCategory.LEARNING])await toggleHabit(ModuleCategory.LEARNING);toast.success(`${cat}已打卡✅`);},[logLearning,habits,toggleHabit]);
  if(isLoading)return<div className="max-w-7xl mx-auto px-4 sm:px-6 py-20"><LoadingSpinner size="lg" text="加载中..."/></div>;
  const isIelts=(cat:string)=>cat==='雅思';

  return(<div className="max-w-7xl mx-auto px-4 sm:px-6 py-6 animate-fade-in">
    <div className="mb-6"><h1 className="text-2xl font-bold flex items-center gap-2 text-purple-500"><GraduationCap className="h-7 w-7"/>{t('learning.title')}</h1><p className="text-sm mt-1 text-slate-400">勾选子板块 · 学习计划 · 思维导图 · 英文阅读(50篇)</p></div>
    <div className="module-card mb-6" style={{'--module-accent':'#8b5cf6'} as React.CSSProperties}><h2 className="section-title" style={{'--module-accent':'#8b5cf6'} as React.CSSProperties}><BookOpen className="h-5 w-5 text-purple-500"/>{t('learning.categories')}</h2><div className="flex flex-wrap gap-2">{LEARNING_CATEGORIES.map(cat=>{const cd=categories.find(c=>c.category===cat);const isActive=cd?.isActive??false;const tc=todayLogs.some(l=>l.category===cat);return(<button key={cat} onClick={()=>toggleCategory(cat)} className={cn('flex items-center gap-2 px-4 py-2.5 rounded-lg transition-all border-2 text-sm font-medium',isActive?'shadow-sm':'')} style={{background:isActive?'#8b5cf612':'var(--color-surface-alt)',borderColor:isActive?'#8b5cf6':'var(--color-border)',color:isActive?'#7c3aed':'var(--color-text-secondary)'}}><span>{cat}</span>{tc&&<CheckCircle2 className="h-3.5 w-3.5 text-emerald-500"/>}</button>);})}</div></div>
    {activeCategories.length===0?<div className="module-card text-center py-12" style={{'--module-accent':'#8b5cf6'} as React.CSSProperties}><BookOpen className="h-12 w-12 mx-auto mb-3 text-slate-300"/><p className="text-sm text-slate-400">请先勾选上方的学习分类</p></div>:
    <div className="grid grid-cols-1 gap-6">{activeCategories.map(cat=>{const catPlans=plans.filter(p=>p.category===cat);const catLogs=todayLogs.filter(l=>l.category===cat);const isComplete=catLogs.some(l=>l.completed);const curTab=activeTabs[cat]||'plan';
    return(<div key={cat} className="module-card" style={{'--module-accent':'#8b5cf6'} as React.CSSProperties}>
      <div className="flex items-center justify-between mb-3"><h3 className="text-sm font-bold text-purple-600">{cat}</h3><button onClick={()=>handleQuickCheck(cat)} className={cn('px-3 py-1 rounded-lg text-xs font-medium')} style={{background:isComplete?'#22c55e18':'var(--color-surface-hover)',color:isComplete?'#22c55e':'var(--color-text-muted)'}}>{isComplete?'✓ 已完成':'标记完成'}</button></div>
      <div className="flex items-center gap-1 mb-4 p-1 rounded-lg bg-slate-100">{['plan','mindmap',...(isIelts(cat)?['reading']:[])].map(tab=><button key={tab} onClick={()=>setActiveTabs(p=>({...p,[cat]:tab}))} className={cn('flex-1 py-1.5 rounded-md text-xs font-medium transition-all',curTab===tab?'bg-white text-purple-600 shadow-sm':'text-slate-500 hover:text-slate-700')}>{tab==='plan'?'📋 学习计划':tab==='mindmap'?'🧠 思维导图':'📖 英文阅读'}</button>)}</div>
      {curTab==='plan'&&<>{catPlans.length>0?<div className="space-y-2 mb-3">{catPlans.map(p=><div key={p.id} className="p-3 rounded-lg bg-surface-alt"><div className="flex items-center justify-between mb-1"><span className="text-sm font-medium text-slate-800">{p.title}</span>{p.isAccepted?<span className="text-xs px-1.5 py-0.5 rounded bg-emerald-100 text-emerald-600">已接受</span>:<button onClick={()=>handleAcceptPlan(p.id)} className="text-xs px-2 py-0.5 rounded btn-primary" style={{'--color-accent':'#8b5cf6','--color-accent-hover':'#7c3aed'} as React.CSSProperties}>接受</button>}</div>{p.methodDescription&&<p className="text-xs text-slate-400">{p.methodDescription}</p>}</div>)}</div>:<div className="text-center py-4 mb-3"><p className="text-xs text-slate-400">暂无计划</p></div>}<button onClick={()=>{setPlanCat(cat);setShowPlanForm(true);}} className="flex items-center justify-center gap-1 px-3 py-2 rounded-lg text-xs text-purple-500 w-full" style={{background:'#8b5cf612'}}><Plus className="h-3.5 w-3.5"/>添加计划</button></>}
      {curTab==='mindmap'&&<MindMapBuilder category={cat} userId={userId}/>}
      {curTab==='reading'&&isIelts(cat)&&<IeltsReading category={cat}/>}
    </div>);})}</div>}
    {showPlanForm&&<><div className="fixed inset-0 z-50 bg-black/30 backdrop-blur-sm" onClick={()=>setShowPlanForm(false)}/><div className="fixed inset-0 z-50 flex items-center justify-center p-4" onClick={()=>setShowPlanForm(false)}><div className="w-full max-w-md p-6 rounded-2xl shadow-2xl bg-white" onClick={e=>e.stopPropagation()}><div className="flex items-center justify-between mb-4"><h3 className="text-lg font-bold text-purple-600">创建{planCat}计划</h3><button onClick={()=>setShowPlanForm(false)}><X className="h-5 w-5 text-slate-400"/></button></div><div className="space-y-3"><input type="text" value={planTitle} onChange={e=>setPlanTitle(e.target.value)} placeholder="计划标题" className="input-field text-sm" autoFocus/><textarea value={planMethod} onChange={e=>setPlanMethod(e.target.value)} placeholder="学习方法描述" className="input-field min-h-[80px] text-sm"/><textarea value={planSchedule} onChange={e=>setPlanSchedule(e.target.value)} placeholder="每日学习规划（可选）" className="input-field min-h-[60px] text-sm"/><input type="text" value={localPath} onChange={e=>setLocalPath(e.target.value)} placeholder="本地资料路径" className="input-field text-sm"/><button onClick={handleCreatePlan} disabled={!planTitle.trim()} className="btn-primary w-full" style={{'--color-accent':'#8b5cf6','--color-accent-hover':'#7c3aed'} as React.CSSProperties}>{t('common.save')}</button></div></div></div></>}
  </div>);
}
